#!/usr/bin/env python3
"""Generate spin-up and spin-down true A(k,omega) cubes on Nomega-style grids.

This mirrors `make_lorentzian_akw_cubes.py` interface but computes:
  A(k,w) = -C * Im[ 1 / (w - xi_k - Sigma^R(k,w) + i*eta_g) ]
with Sigma^R(k,w) = ReS + i ImS coming from `simga_test.imsigma_ret`
and KK reconstruction for ReS.
"""

from __future__ import annotations

import argparse
from concurrent.futures import ThreadPoolExecutor, as_completed
from datetime import datetime
